/* Crosshair – Dancepad (own implementation) */
function dancepad_crosshair() {
  const isBreakdance = window.location.href.includes("breakdance_iframe");

  document.querySelectorAll('.dan-crosshair').forEach(el => {
    if (isBreakdance && el.getAttribute('data-disable-builder') === '1') return;
    if (el.dataset.danCrosshairReady) return;
    el.dataset.danCrosshairReady = '1';

    const hBar = el.querySelector('.dan-crosshair__line-horizontal');
    const vBar = el.querySelector('.dan-crosshair__line-vertical');
    if (!hBar || !vBar) return;

    const ease = parseFloat(el.getAttribute('data-attachness')) || 0.15;

    /* Position state – flat objects instead of nested structures. */
    const goal = { x: 0, y: 0 };
    const cur  = { x: 0, y: 0 };

    gsap.set([hBar, vBar], { opacity: 0 });

    /* Smooth-step loop: cur moves toward goal each frame. */
    function tick() {
      cur.x += (goal.x - cur.x) * ease;
      cur.y += (goal.y - cur.y) * ease;
      gsap.set(vBar, { x: cur.x });
      gsap.set(hBar, { y: cur.y });
      requestAnimationFrame(tick);
    }

    /* Track pointer relative to the container. */
    el.addEventListener('mousemove', function (ev) {
      const box = el.getBoundingClientRect();
      goal.x = ev.clientX - box.left;
      goal.y = ev.clientY - box.top;

      const inside = ev.clientX >= box.left && ev.clientX <= box.right &&
                     ev.clientY >= box.top  && ev.clientY <= box.bottom;
      gsap.to([hBar, vBar], { opacity: inside ? 1 : 0 });
    });

    /* First move: snap instantly so there's no "fly in" from 0,0. */
    el.addEventListener('mousemove', function () {
      cur.x = goal.x;
      cur.y = goal.y;
      gsap.to([hBar, vBar], { opacity: 1 });
      requestAnimationFrame(tick);
    }, { once: true });
  });
}